import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// Generated by tools/music/music_sounds.py from the music catalogue, tools/music/tracks.json.
const CATALOG_PATH = path.resolve(__dirname, "../../data/music-sounds.json");

let sounds: ReadonlyMap<string, number | null> | null = null;
const load = (): ReadonlyMap<string, number | null> =>
  (sounds ??= new Map(Object.entries((JSON.parse(readFileSync(CATALOG_PATH, "utf8")) as { sounds: Record<string, number | null> }).sounds)));

/**
 * A Music Sound our maps load that plays real audio (CHECKS.md M1), the game's in our dependency
 * stack and not one of its silent or empty ids: its file's length in ms (the longest it may play),
 * null when unmeasured. Undefined for any other id.
 */
export function loadedMusicSoundMs(id: string): number | null | undefined {
  const seconds = load().get(id);
  return seconds === undefined || seconds === null ? seconds : Math.round(seconds * 1000);
}
